style.css:
@-moz-document domain("roblox.com") {
html, body, #app, .root, .theme-base {
    background-color: #f9f9f9 !important;
    color: #111 !important;
  }

  .navbar,
  .container-main,
  .content,
  .page-content,
  .section,
  .card {
    background-color: rgba(255, 255, 255, 0.8) !important;
    backdrop-filter: blur(2px);
  }

  a, h1, h2, h3, h4, h5, h6, p, span, div {
    color: #111 !important;
  }
}
